const base = 'https://intranet.dl.diania.es';
const rutas = ['/api/docs.json', '/api/openapi.json', '/api/openapi.yaml', '/api/swagger.json', '/api/docs/openapi.json', '/api/docs?format=json', '/docs.openapi', '/api/spec', '/api/docs'];
return rutas.map(function (r) { return { json: { url: base + r } }; });

const lista = $('URLs candidatas').all().map(function (i) { return i.json.url; });
return $input.all().map(function (it, idx) {
  const r = it.json || {};
  const data = typeof r.data === 'string' ? r.data : JSON.stringify(r.data || r.body || r.error || '');
  let paths = null;
  try { const j = JSON.parse(data); if (j && j.paths) { paths = Object.keys(j.paths); } } catch (e) {}
  return { json: { url: lista[idx], status: r.statusCode, len: data.length, head: data.slice(0, 160), paths: paths } };
});
